const strList = (v: unknown, n: number, cap: number) => arr(v).map((x) => str(x, cap)).filter(Boolean).slice(0, n);
export function readBuildExecution(v: unknown): BuildExecution {
  const o = obj(v);
  const q = obj(o.qa), r = obj(o.redirects), p = obj(o.previous);
  const qa: Partial<Record<BuildQaKey, boolean>> = {};
  for (const k of BUILD_QA_KEYS) if (typeof q[k] === 'boolean') qa[k] = q[k] as boolean;
  const S = (k: string, cap = 500) => str(o[k], cap);
  return {
    started_at: S('started_at', 40), completed_at: S('completed_at', 40), template_id: S('template_id', 80), config_version: S('config_version', 40),
    repository_url: S('repository_url'), repository_name: S('repository_name', 100), branch: S('branch', 100), local_path: S('local_path'),
    cloudflare_project: S('cloudflare_project', 100), preview_url: S('preview_url'), deployment_id: S('deployment_id', 100), deployment_status: S('deployment_status', 60),
    noindex_confirmed: typeof o.noindex_confirmed === 'boolean' ? o.noindex_confirmed : null, output_dir: S('output_dir', 200), commit_hash: S('commit_hash', 64),
    result_imported_at: S('result_imported_at', 40), result_status: oneOf(BUILD_RESULT_STATUSES, o.result_status, ''),
    warnings: strList(o.warnings, 100, 500), errors: strList(o.errors, 100, 500), qa,
    pages: strList(o.pages, 600, 300), services: strList(o.services, 100, 160), locations: strList(o.locations, 100, 160), assets: strList(o.assets, 300, 600),
    redirects: { kept: count(r.kept), redirected: count(r.redirected), retired: count(r.retired), unresolved: strList(r.unresolved, 600, 500), issues: strList(r.issues, 200, 500) },
    seed_hits: strList(o.seed_hits, 100, 300),
    upgrade: readUpgradeReview(o.upgrade),
    standard: readStandardReport(o.standard),
    previous: Object.keys(p).length ? { commit_hash: str(p.commit_hash, 64), repository_url: str(p.repository_url, 500), preview_url: str(p.preview_url, 500), result_status: oneOf(BUILD_RESULT_STATUSES, p.result_status, ''), imported_at: str(p.imported_at, 40) } : null,
    old_urls: readOldUrlCheck(o.old_urls),
  };
}

export interface MappingState {
  /** template service id → included in the build. Absent = no decision (the mapper proposes). */
  services: Record<string, boolean>;
  /** source service candidate (normalised name) → template service id, or 'ignore'. */
  candidate_map: Record<string, string>;
  /** town key → { serves, page, note }. Absent = no decision. page defaults OFF (no doorway pages) — the
   *  home town too: the HOME PAGE owns "<trade> in <home town>". `note` = the genuinely local content
   *  that justifies a town page (real jobs there, access, landmarks); a page without one blocks. */
  locations: Record<string, { serves?: boolean; page?: boolean; note?: string }>;
  /** asset slot id → assigned asset source URLs (only USE assets are ever published). */
  assets: Record<string, string[]>;
  /** template field id → an operator value for a field the ledger has no fact for (choices). */
  fields: Record<string, string>;
}
const MAP_KEY = /^[a-z0-9][a-z0-9_.:-]{0,79}$/;
const mapKey = (k: string) => k.toLowerCase().trim().slice(0, 80);
function readCandidates(v: unknown): ReconCandidate[] {
  const seen = new Set<string>();
  return arr(v).map((x) => { const c = obj(x); return { name: str(c.name, 120), source_url: str(c.source_url, 500), context: str(c.context, 300) }; })
    .filter((c) => c.name && !seen.has(c.name.toLowerCase()) && !!seen.add(c.name.toLowerCase())).slice(0, MAX_RECON_CANDIDATES);
}
function readMapping(v: unknown): MappingState {
  const o = obj(v);
  const out: MappingState = { services: {}, candidate_map: {}, locations: {}, assets: {}, fields: {} };
  for (const [k, b] of Object.entries(obj(o.services)).slice(0, 200)) if (MAP_KEY.test(mapKey(k)) && typeof b === 'boolean') out.services[mapKey(k)] = b;
  for (const [k, b] of Object.entries(obj(o.candidate_map)).slice(0, 300)) { const key = str(k, 120).toLowerCase(); const val = str(b, 80); if (key && MAP_KEY.test(val)) out.candidate_map[key] = val; }
  for (const [k, b] of Object.entries(obj(o.locations)).slice(0, 300)) {
    const key = str(k, 120).toLowerCase(); const l = obj(b); if (!key) continue;
    const e: { serves?: boolean; page?: boolean; note?: string } = {};
    if (typeof l.serves === 'boolean') e.serves = l.serves;
    if (typeof l.page === 'boolean') e.page = l.page;
    const note = str(l.note, 600);
    if (note) e.note = note;
    if ('serves' in e || 'page' in e || 'note' in e) out.locations[key] = e;
  }
  for (const [k, list] of Object.entries(obj(o.assets)).slice(0, 40)) {
    if (!MAP_KEY.test(mapKey(k))) continue;
    /* https, or file:/// for a client-supplied file on the build machine (fix workstream 6). */
    const urls = [...new Set(arr(list).map((u) => str(u, 500)).filter((u) => /^(https?:\/\/|file:\/\/\/)/i.test(u)))].slice(0, 60);
    if (urls.length) out.assets[mapKey(k)] = urls;
  }
  for (const [k, val] of Object.entries(obj(o.fields)).slice(0, 100)) if (MAP_KEY.test(mapKey(k))) { const s = str(val, 500); if (s) out.fields[mapKey(k)] = s; }
  return out;
}

/* ── V2: visual comparison (faithful rebuild) — state only; no image comparison is run. ───────── */

export const DEFAULT_COMPARE_WIDTHS = [1440, 1024, 768, 390] as const;
export const COMPARE_STATUSES = ['not_checked', 'differences', 'approved'] as const;
export type CompareStatus = (typeof COMPARE_STATUSES)[number];
export const COMPARE_STATUS_LABELS: Record<CompareStatus, string> = {
  not_checked: 'Not checked', differences: 'Differences found', approved: 'Approved',
};
export interface CompareResult { family: PageFamily; status: CompareStatus; notes: string }
export interface VisualComparison {
  /** Blank = the existing site URL. */
  source_url: string;
  /** Blank = the Cloudflare preview URL. */
  preview_url: string;
  widths: number[];
  results: CompareResult[];
}

/* ── V2: bespoke → template, later. Records intent only; nothing is extracted. ────────────────── */
export interface TemplatePromotion { candidate: boolean; proposed_name: string; proposed_trade: string; notes: string }

export interface WebsiteBuildState {
  version: typeof WEBSITE_BUILD_VERSION;
  route: BuildRoute | '';
  template_id: string;
  rebuild_style: RebuildStyle | '';
  copy_ownership: CopyOwnership | '';
  /* source website */
  source_site_url: string;
  source_still_live: SiteLiveState;
  source_platform: string;
  last_captured_at: string;
  /* code */
  repo_name: string;
  github_owner: string;
  repo_url: string;
  local_repo_path: string;
  dev_command: string;
  build_command: string;
  build_output_dir: string;
  /* preview */
  cloudflare_project: string;
  /** F17: how that project deploys, which account it lives in (a label — never a credential), and
   *  its production / preview branches. Blank branches read as the defaults (cloudflareBranches). */
  cloudflare_mode: CloudflareMode | '';
  cloudflare_account: string;
  cloudflare_production_branch: string;
  cloudflare_preview_branch: string;
  dev_url: string;
  preview_url: string;
  preview_status: PreviewStatus;
  preview_noindex_confirmed: boolean;
  /* production */
  production_url: string;
  production_status: ProductionStatus;
  custom_domain_status: CustomDomainStatus;
  www_redirect_status: WwwRedirectStatus;
  canonical_domain: string;
  latest_commit: string;
  /* bespoke design references (existing Findable sites / templates) */
  design_references: string;
  notes: string;
  capture: CaptureState;
  manifest: SourceManifest;
  visual: VisualComparison;
  promotion: TemplatePromotion;
  /** Phase 2: the last recon import (Claude crawled; LeadFinderOS stored). */
  recon: ReconState;
  /** Phase 3: Paul's template-mapping decisions. Values themselves live in the fact ledger; this
   *  holds only choices the ledger has no row for (include a service, serve / page a town, which
   *  asset fills which slot, a template choice field). */
  mapping: MappingState;
  /** Phase 4: the last build Claude Code ran (prompt copied → result imported). */
  build_execution: BuildExecution;
  facts: BuildFact[];
  pages: ArchPage[];
  redirects: Redirect[];
  qa: Partial<Record<QaKey, boolean>>;
  /** Route-specific stage checklist ticks, keyed route.stage.key (buildRoutes.ts). */
  checks: Record<string, true>;
  /** The Findable quality standard: existing-site strengths + their decisions, content completeness. */
  quality: QualityState;
  /** Fix workstream 6 (2026-10-04): the enquiry form, switched on HERE (siteForm.ts) — site-enquiry
   *  reads it, so a new client's form needs no code edit or deploy. */
  form: SiteFormState;
  /** The site quality gate run on the LIVE domain (--url, not a preview), imported by Paul after the
   *  production deploy. "Production checked" cannot be ticked until it passed (websiteLaunch.ts). */
  production_gate: ProductionGateRecord;
  /** Paul's corrections to the generated site before launch, in his words — printed into the
   *  Corrections prompt (buildExecution.ts correctionPrompt). */
  corrections: string;
  /** The site's main call to action, in Paul's words ("Call Gareth", "Send an enquiry"). Blank = the
   *  builder chooses from the verified contact routes. */
  primary_cta: string;
  /** RANKING PROTECTION (2026-10-10, oldPages.ts): the old site's addresses, the new page each lands
   *  on, or the explicit "no old site" record. */
  old_pages: OldPagesState;
}

/** The production gate report, kept small: the verdict and the failing / warning check labels. */
export interface ProductionGateRecord {
  imported_at: string;
  version: number | null;
  domain: string;
  mode: string;
  preview: boolean;
  passed: boolean | null;
  fails: string[];
  warns: string[];
  /** The old addresses as the LIVE gate run fetched them (oldPages.ts). */
  old_urls: OldUrlCheck;
}
export const EMPTY_PRODUCTION_GATE: ProductionGateRecord = { imported_at: '', version: null, domain: '', mode: '', preview: false, passed: null, fails: [], warns: [], old_urls: EMPTY_OLD_URL_CHECK };
export function readProductionGate(v: unknown): ProductionGateRecord {
  const o = obj(v);
  const list = (x: unknown) => arr(x).map((y) => str(y, 300)).filter(Boolean).slice(0, 40);
  return {
    imported_at: str(o.imported_at, 40), version: typeof o.version === 'number' ? o.version : null,
    domain: str(o.domain, 253).toLowerCase(), mode: str(o.mode, 10), preview: o.preview === true,
    passed: o.passed === true ? true : o.passed === false ? false : null, fails: list(o.fails), warns: list(o.warns),
    old_urls: readOldUrlCheck(o.old_urls),
  };
}

/* The plain string fields and their caps. One list, read by both the parser and the normaliser. */
const STRING_FIELDS = {
  template_id: 80, repo_name: 100, github_owner: 100, repo_url: 500, local_repo_path: 500,
  cloudflare_project: 100, dev_url: 500, preview_url: 500, production_url: 500,
  cloudflare_account: 120, cloudflare_production_branch: 100, cloudflare_preview_branch: 100,
  canonical_domain: 253, latest_commit: 80, notes: 8000,
  source_site_url: 500, source_platform: 100, last_captured_at: 40,
  dev_command: 200, build_command: 200, build_output_dir: 200, design_references: 2000,
  corrections: 4000, primary_cta: 200,
} as const;
type StringField = keyof typeof STRING_FIELDS;

/* Collection caps — generous for a trade site (MCL's rebuild had 289 legacy URLs), but bounded so
   one paste cannot bloat the row. */
export const MAX_FACTS = 120;
export const MAX_PAGES = 200;
export const MAX_REDIRECTS = 600;
export const MAX_MANIFEST_PAGES = 600;
export const MAX_MANIFEST_ASSETS = 300;
export const MAX_MANIFEST_INTERACTIONS = 100;

const EMPTY_MANIFEST: SourceManifest = {
  pages: [], assets: [], interactions: [], redirect_candidates: [],
  design: { fonts: '', colours: '', layout_notes: '', component_notes: '' },
  seo: { metadata: '', canonical: '', schema: '', sitemap: '', robots: '', tracking: '' },
};

export const EMPTY_WEBSITE_BUILD: WebsiteBuildState = {
  version: WEBSITE_BUILD_VERSION,
  route: '', template_id: '', rebuild_style: '', copy_ownership: '',
  source_site_url: '', source_still_live: 'unknown', source_platform: '', last_captured_at: '',
  repo_name: '', github_owner: '', repo_url: '', local_repo_path: '', dev_command: '', build_command: '', build_output_dir: '',
  cloudflare_project: '', dev_url: '', preview_url: '', preview_status: 'not_deployed', preview_noindex_confirmed: false,
  cloudflare_mode: '', cloudflare_account: '', cloudflare_production_branch: '', cloudflare_preview_branch: '',
  production_url: '', production_status: 'not_live', custom_domain_status: 'not_started', www_redirect_status: 'not_checked',
  canonical_domain: '', latest_commit: '', design_references: '', notes: '',
  capture: { status: 'not_started', url_count: null, asset_count: null, notes: '' },
  manifest: EMPTY_MANIFEST,
  visual: { source_url: '', preview_url: '', widths: [...DEFAULT_COMPARE_WIDTHS], results: [] },
  promotion: { candidate: false, proposed_name: '', proposed_trade: '', notes: '' },
  recon: { prompt_copied_at: '', imported_at: '', source_url: '', captured_at: '', pages_total: null, assets_total: null, review: [], services: [], towns: [] },
  mapping: { services: {}, candidate_map: {}, locations: {}, assets: {}, fields: {} },
  build_execution: EMPTY_BUILD_EXECUTION,
  facts: [], pages: [], redirects: [], qa: {}, checks: {}, quality: EMPTY_QUALITY,
  form: EMPTY_SITE_FORM, production_gate: EMPTY_PRODUCTION_GATE, corrections: '', primary_cta: '', old_pages: EMPTY_OLD_PAGES,
};

const obj = (v: unknown): Record<string, unknown> =>
  (v && typeof v === 'object' && !Array.isArray(v)) ? v as Record<string, unknown> : {};
const str = (v: unknown, cap: number) => (typeof v === 'string' ? v : v == null ? '' : String(v)).trim().slice(0, cap);
const arr = (v: unknown): unknown[] => (Array.isArray(v) ? v : []);
/** ⛔ A token outside its list is dropped to the fallback, never stored as itself. */
function oneOf<T extends string>(list: readonly T[], v: unknown, fallback: T | ''): T | '' {
  const s = str(v, 80);
  return (list as readonly string[]).includes(s) ? s as T : fallback;
}
/** A token with a non-empty default. */
const tok = <T extends string>(list: readonly T[], v: unknown, fallback: T): T => (oneOf(list, v, fallback) || fallback) as T;
function count(v: unknown): number | null {
  if (v === null || v === undefined || v === '') return null;
  const n = Math.floor(Number(v));
  return Number.isFinite(n) && n >= 0 && n < 1_000_000 ? n : null;
}

function readFact(raw: unknown): BuildFact | null {
  const o = obj(raw);
  const key = str(o.key, 80);
  if (!key) return null;
  return {
    key,
    label: str(o.label, 120) || key,
    value: str(o.value, 2000),
    status: tok(FACT_STATUSES, o.status, 'detected'),
    source: str(o.source, 120),
    source_url: str(o.source_url, 500),
    notes: str(o.notes, 1000),
    basis: oneOf(FACT_BASES, o.basis, ''),
  };
}

function readPage(raw: unknown, i: number): ArchPage | null {
  const o = obj(raw);
  const page: ArchPage = {
    id: str(o.id, 40) || `p${i + 1}`,
    family: tok(PAGE_FAMILIES, o.family, 'other'),
    title: str(o.title, 200),
    path: str(o.path, 500),
    action: tok(PAGE_ACTIONS, o.action, 'undecided'),
    old_url: str(o.old_url, 500),
    target: str(o.target, 500),
    notes: str(o.notes, 1000),
    meta: str(o.meta, 300),
  };
  /* A row with nothing in it is not a page. */
  return (page.title || page.path || page.old_url) ? page : null;
}

function readRedirect(raw: unknown): Redirect | null {
  const o = obj(raw);
  const r = { from: str(o.from, 500), to: str(o.to, 500), reason: str(o.reason, 300) };
  return r.from ? r : null;
}

/** Read a manifest (a stored one, or a pasted capture/manifest.json) into the capped shape. */
export function parseManifest(raw: unknown): SourceManifest {
  const o = obj(raw);
  const d = obj(o.design), s = obj(o.seo);
  return {
    pages: arr(o.pages).map((x) => {
      const p = obj(x);
      const code = Math.floor(Number(p.status_code));
      return { url: str(p.url, 500), type: tok(PAGE_FAMILIES, p.type, 'other'), title: str(p.title, 200), h1: str(p.h1, 200),
        purpose: str(p.purpose, 300), screenshots: arr(p.screenshots).map((v) => str(v, 300)).filter(Boolean).slice(0, 8),
        status_code: p.status_code != null && code >= 100 && code <= 599 ? code : null,
        sections: arr(p.sections).map((v) => str(v, 120)).filter(Boolean).slice(0, 20) };
    }).filter((p) => p.url).slice(0, MAX_MANIFEST_PAGES),
    assets: arr(o.assets).map((x) => {
      const a = obj(x);
      return { source_url: str(a.source_url, 500), type: tok(ASSET_TYPES, a.type, 'other'), purpose: str(a.purpose, 200),
        location: str(a.location, 300), approval: tok(ASSET_APPROVALS, a.approval, 'pending'),
        page_url: str(a.page_url, 500), suggested_filename: str(a.suggested_filename, 120), ownership: tok(ASSET_OWNERSHIPS, a.ownership, 'unknown'),
        ...(a.origin === 'client' ? { origin: 'client' as const } : {}) };
    }).filter((a) => a.source_url || a.location).slice(0, MAX_MANIFEST_ASSETS),
    redirect_candidates: arr(o.redirect_candidates).map(readRedirect).filter((r): r is Redirect => !!r).slice(0, MAX_REDIRECTS),
    interactions: arr(o.interactions).map((x) => {
      const it = obj(x);
      return { kind: tok(INTERACTION_KINDS, it.kind, 'other'), where: str(it.where, 300), notes: str(it.notes, 500) };
    }).filter((it) => it.where || it.notes).slice(0, MAX_MANIFEST_INTERACTIONS),
    design: { fonts: str(d.fonts, 1000), colours: str(d.colours, 1000), layout_notes: str(d.layout_notes, 4000), component_notes: str(d.component_notes, 4000) },
    seo: { metadata: str(s.metadata, 2000), canonical: str(s.canonical, 500), schema: str(s.schema, 2000), sitemap: str(s.sitemap, 500), robots: str(s.robots, 1000), tracking: str(s.tracking, 1000) },
  };
}

function readWidths(v: unknown): number[] {
  if (!Array.isArray(v)) return [...DEFAULT_COMPARE_WIDTHS];
  const out = [...new Set(v.map((n) => Math.floor(Number(n))).filter((n) => Number.isFinite(n) && n >= 240 && n <= 3840))].slice(0, 8);
  return out.length ? out : [...DEFAULT_COMPARE_WIDTHS];
}

/** V1 → V2: the operator's own V1 choice under its V2 name. Absent stays absent. */
function routeFromV1(o: Record<string, unknown>): BuildRoute | '' {
  const m = str(o.build_mode, 20);
  if (m === 'template') return 'template_rebuild';
  if (m === 'rebuild') return 'faithful_rebuild';
  return '';
}

/**
 * Read (browser) or normalise (server) a website_build value into the complete, allowlisted V2
 * state. The one rule both sides use. Unknown keys vanish; unknown tokens fall to their safe
 * default; a V1 row (no `version`) is read through the V1 → V2 rules in the header.
 */
export function parseWebsiteBuild(raw: unknown): WebsiteBuildState {
  const o = obj(raw);
  const isV1 = o.version !== WEBSITE_BUILD_VERSION;
  const v1Deploy = isV1 ? str(o.deploy_status, 20) : '';
  const out: WebsiteBuildState = {
    ...EMPTY_WEBSITE_BUILD,
    route: oneOf(BUILD_ROUTES, o.route, '') || (isV1 ? routeFromV1(o) : ''),
    rebuild_style: oneOf(REBUILD_STYLES, o.rebuild_style, ''),
    copy_ownership: oneOf(COPY_OWNERSHIPS, o.copy_ownership, ''),
    source_still_live: tok(SITE_LIVE_STATES, o.source_still_live, 'unknown'),
    preview_status: tok(PREVIEW_STATUSES, o.preview_status, v1Deploy === 'preview' || v1Deploy === 'production' ? 'deployed' : 'not_deployed'),
    preview_noindex_confirmed: o.preview_noindex_confirmed === true,
    cloudflare_mode: oneOf(CLOUDFLARE_MODES, o.cloudflare_mode, ''),
    production_status: tok(PRODUCTION_STATUSES, o.production_status, v1Deploy === 'production' ? 'deployed' : 'not_live'),
    custom_domain_status: tok(CUSTOM_DOMAIN_STATUSES, o.custom_domain_status, 'not_started'),
    www_redirect_status: tok(WWW_REDIRECT_STATUSES, o.www_redirect_status, 'not_checked'),
  };
  for (const k of Object.keys(STRING_FIELDS) as StringField[]) out[k] = str(o[k], STRING_FIELDS[k]);
  const c = obj(o.capture);
  out.capture = {
    status: tok(CAPTURE_STATUSES, c.status, 'not_started'),
    url_count: count(c.url_count),
    asset_count: count(c.asset_count),
    notes: str(c.notes, 4000),
  };
  out.manifest = parseManifest(o.manifest);
  const vis = obj(o.visual);
  const seenFam = new Set<string>();
  out.visual = {
    source_url: str(vis.source_url, 500),
    preview_url: str(vis.preview_url, 500),
    widths: readWidths(vis.widths),
    results: arr(vis.results).map((x) => {
      const r = obj(x);
      return { family: tok(PAGE_FAMILIES, r.family, 'other'), status: tok(COMPARE_STATUSES, r.status, 'not_checked'), notes: str(r.notes, 1000) };
    }).filter((r) => !seenFam.has(r.family) && !!seenFam.add(r.family)),
  };
  const pr = obj(o.promotion);
  out.promotion = { candidate: pr.candidate === true, proposed_name: str(pr.proposed_name, 120), proposed_trade: str(pr.proposed_trade, 120), notes: str(pr.notes, 2000) };
  const rc = obj(o.recon);
  out.recon = {
    prompt_copied_at: str(rc.prompt_copied_at, 40), imported_at: str(rc.imported_at, 40),
    source_url: str(rc.source_url, 500), captured_at: str(rc.captured_at, 40),
    pages_total: count(rc.pages_total), assets_total: count(rc.assets_total),
    review: arr(rc.review).map((x) => {
      const r = obj(x);
      return { kind: tok(RECON_REVIEW_KINDS, r.kind, 'warning'), key: str(r.key, 80), label: str(r.label, 160), detail: str(r.detail, 1000), resolved: r.resolved === true };
    }).filter((r) => r.label || r.detail).slice(0, MAX_RECON_REVIEW),
    services: readCandidates(rc.services), towns: readCandidates(rc.towns),
  };
  out.mapping = readMapping(o.mapping);
  out.build_execution = readBuildExecution(o.build_execution);
  const seen = new Set<string>();
  out.facts = arr(o.facts).map(readFact)
    .filter((f): f is BuildFact => !!f && !seen.has(f.key) && !!seen.add(f.key)).slice(0, MAX_FACTS);
  out.pages = arr(o.pages).map(readPage)
    .filter((p): p is ArchPage => !!p).slice(0, MAX_PAGES);
  out.redirects = arr(o.redirects).map(readRedirect)
    .filter((r): r is Redirect => !!r).slice(0, MAX_REDIRECTS);
  const qa = obj(o.qa);
  out.qa = {};
  for (const k of QA_KEYS) if (qa[k] === true) (out.qa as Record<string, boolean>)[k] = true;
  const ch = obj(o.checks);
  out.checks = {};
  for (const k of ALL_ROUTE_CHECK_IDS) if (ch[k] === true) out.checks[k] = true;
  out.quality = readQuality(o.quality);
  out.form = readSiteForm(o.form);
  out.production_gate = readProductionGate(o.production_gate);
  out.old_pages = readOldPages(o.old_pages);
  return out;
}

const isEmptyValue = (v: unknown): boolean => {
  if (v === '' || v === null || v === false) return true;
  if (Array.isArray(v)) return v.length === 0;
  if (typeof v === 'object') return Object.values(v as object).every(isEmptyValue);
  return false;
};

/** The server's write rule: the parsed state, with empty values left out so the row stays small.
 *  `version` is always written — it is what tells the next read this row is V2. */
export function normaliseWebsiteBuild(raw: unknown): Record<string, unknown> {
  const s = parseWebsiteBuild(raw);
  const out: Record<string, unknown> = { version: WEBSITE_BUILD_VERSION };
  for (const [k, v] of Object.entries(s)) {
    if (k === 'version' || isEmptyValue(v)) continue;
    out[k] = v;
  }
  return out;
}

/* ── derived progress ─────────────────────────────────────────────────────────────────────────── */

export const STAGES = ['intake', 'capture', 'architecture', 'build_pack', 'preview', 'qa', 'live'] as const;
export type Stage = (typeof STAGES)[number];
export const STAGE_LABELS: Record<Stage, string> = {
  intake: 'Intake', capture: 'Capture', architecture: 'Architecture', build_pack: 'Build pack',
  preview: 'Preview', qa: 'QA', live: 'Live',
};

export interface StageStatus { stage: Stage; done: boolean; applicable: boolean; detail: string }

/** Is the route decision complete enough to generate anything from? */
export function modeComplete(s: WebsiteBuildState): boolean {
  if (s.route === 'template_rebuild') return !!s.template_id;
  if (s.route === 'faithful_rebuild') return !!s.rebuild_style && !!s.copy_ownership;
  if (s.route === 'bespoke') return true;
  return false;
}

/** Capture applies to a faithful rebuild always, to a bespoke build always (it is discovery there),
 *  and to a template rebuild only when there is an old site to take facts and assets from. */
export function captureApplies(s: WebsiteBuildState, hasExistingSite: boolean): boolean {
  if (s.route === 'faithful_rebuild' || s.route === 'bespoke') return true;
  return s.route === 'template_rebuild' && hasExistingSite;
}

/** How far capture has got — ONE wording for the Capture stage and every prompt (F15, BS4 pilot:
 *  the build prompt said "Capture: not started" after a 298-page recon had been imported). An
 *  imported recon IS proof of capture; nobody has to tick it again. */
export function captureSummary(s: WebsiteBuildState): string {
  const counts = (u: number | null, a: number | null) => (u != null ? ' · ' + u + ' URLs' : '') + (a != null ? ' · ' + a + ' assets' : '');
  if (s.capture.status === 'captured') return 'Captured' + counts(s.capture.url_count, s.capture.asset_count);
  if (s.recon.imported_at) return 'Recon imported ' + s.recon.imported_at.slice(0, 10) + counts(s.manifest.pages.length, s.manifest.assets.length);
  return CAPTURE_STATUS_LABELS[s.capture.status] + counts(s.capture.url_count, s.capture.asset_count);
}

export interface StageInputs {
  state: WebsiteBuildState;
  hasExistingSite: boolean;
  /** Facts still waiting for Paul's decision (status `detected`). */
  factsAwaiting: number;
  /** Architecture problems that block (redirect loops / chains). */
  architectureErrors: number;
  /** Required setup values still blank (repo name, local path…). */
  setupMissing: string[];
  /** THE build blockers — executionBlockers (buildExecution.ts), the same list that gates the Build
   *  Execution prompt and the "Ready to build" badge. Absent = not assessed. (F14, BS4 pilot: the
   *  stage said "Finish intake and architecture first" while the pack said Ready to build, because
   *  the stage demanded every fact decided — held claims are allowed; they are left out.) */
  buildBlockers?: string[];
}

export function websiteBuildStages(i: StageInputs): StageStatus[] {
  const s = i.state;
  const qaPreview = requiredPreviewQa(i.hasExistingSite);
  const qaDone = qaPreview.length - outstandingPreviewQa(s, i.hasExistingSite).length;
  const capApplies = captureApplies(s, i.hasExistingSite);
  const intakeDone = modeComplete(s) && i.factsAwaiting === 0;
  const archDone = s.pages.length > 0 && i.architectureErrors === 0;
  return [
    { stage: 'intake', applicable: true, done: intakeDone,
      detail: !modeComplete(s) ? 'Choose the build route' : i.factsAwaiting ? `${i.factsAwaiting} fact(s) need a decision` : 'Route chosen, facts reviewed' },
    { stage: 'capture', applicable: capApplies, done: !capApplies || s.capture.status === 'captured' || reconInventoryReady(s, i.hasExistingSite),
      detail: !capApplies ? 'Not needed for this build' : captureSummary(s) },
    { stage: 'architecture', applicable: true, done: archDone,
      detail: `${s.pages.length} page(s) · ${s.redirects.length} redirect(s)${i.architectureErrors ? ` · ${i.architectureErrors} problem(s)` : ''}` },
    (() => {
      /* ⛔ ONE readiness: the build blockers (+ plan errors, which block the architecture). Never a
         second rule that can disagree with the Ready to build badge. */
      const blockers = i.buildBlockers ? [...i.buildBlockers, ...(i.architectureErrors ? [i.architectureErrors + ' page-plan problem(s)'] : [])] : null;
      return { stage: 'build_pack' as Stage, applicable: true, done: !!blockers && blockers.length === 0,
        detail: !blockers ? 'Not assessed yet' : blockers.length ? `Not ready to build: ${blockers.length} blocker(s)` : 'Ready to build' };
    })(),
    { stage: 'preview', applicable: true, done: !!s.preview_url, detail: s.preview_url ? `${s.preview_url} · ${PREVIEW_STATUS_LABELS[s.preview_status].toLowerCase()}` : 'No preview URL yet' },
    { stage: 'qa', applicable: true, done: qaDone === qaPreview.length, detail: `${qaDone} of ${qaPreview.length} checks` },
    /* The rule weeklyCheck.weeklyStart reads too (production URL + "Production checked"); the SAVE refuses
       that tick until the live-domain gate passed (websiteLaunch.ts), so the shared rule stays honest. */
    { stage: 'live', applicable: true, done: !!s.production_url && s.qa.production_checked === true,
      detail: s.production_url ? (s.qa.production_checked ? `${s.production_url} · verified` : `${s.production_url} · ${s.production_gate.passed === true ? 'live gate passed — tick Production checked' : 'not verified (import the live gate report)'}`) : 'Not live' },
  ];
}

/** The page families a visual comparison covers: the families of the pages being built. */
export function compareFamilies(s: WebsiteBuildState): PageFamily[] {
  const fams = s.pages.filter((p) => p.action === 'keep' || p.action === 'create').map((p) => p.family);
  const fromManifest = s.manifest.pages.map((p) => p.type);
  const all = fams.length ? fams : fromManifest;
  return PAGE_FAMILIES.filter((f) => all.includes(f));
}

/** The Visual Comparison prompt's reply ("service: approved" / "homepage: differences — nav wraps")
 *  → results, merged over the existing ones. Lines that name no known family are ignored. */
export function parseCompareReply(text: string, existing: CompareResult[]): CompareResult[] {
  const byFam = new Map(existing.map((r) => [r.family, r]));
  for (const raw of text.split(/\r?\n/)) {
    const m = /^\s*[-*]?\s*([a-z_]+)\s*:\s*(approved|differences)\b\s*[—–-]?\s*(.*)$/i.exec(raw);
    if (!m) continue;
    const fam = m[1].toLowerCase();
    if (!(PAGE_FAMILIES as readonly string[]).includes(fam)) continue;
    byFam.set(fam as PageFamily, { family: fam as PageFamily, status: m[2].toLowerCase() as CompareStatus, notes: m[3].trim().slice(0, 1000) });
  }
  return PAGE_FAMILIES.filter((f) => byFam.has(f)).map((f) => byFam.get(f)!);
}

/* ── Phase 2: recon status — DERIVED from what is stored, never stored itself. ─────────────── */

export const RECON_STATUSES = ['not_started', 'prompt_copied', 'imported', 'needs_review', 'complete'] as const;
export type ReconStatus = (typeof RECON_STATUSES)[number];
export const RECON_STATUS_LABELS: Record<ReconStatus, string> = {
  not_started: 'Not started', prompt_copied: 'Prompt copied', imported: 'Imported', needs_review: 'Needs review', complete: 'Complete',
};

/** A recon counts as a page inventory once it is imported with pages — or, with no old site to
 *  crawl (bespoke discovery), once it is imported at all. */
export function reconInventoryReady(s: WebsiteBuildState, hasExistingSite: boolean): boolean {
  if (!s.recon.imported_at) return false;
  return s.manifest.pages.length > 0 || !hasExistingSite;
}

/** Open review items: unresolved unknowns / warnings, and conflicts whose fact is still undecided. */
export function openReconReview(s: WebsiteBuildState, isFactOpen: (key: string) => boolean): ReconReviewItem[] {
  return s.recon.review.filter((r) => !r.resolved && (r.kind !== 'conflict' || !r.key || isFactOpen(r.key)));
}

/**
 * Complete = imported, a page inventory exists, and what needs approval is surfaced AND decided.
 * Unknowns that must wait for the client do not block — they are resolved (dismissed) by Paul, or
 * they stay visible as "needs review" without stopping the next stage (Capture's DONE is
 * reconInventoryReady, which does not require them answered).
 */
export function reconStatus(s: WebsiteBuildState, opts: { hasExistingSite: boolean; factsAwaiting: number; openReview: number }): ReconStatus {
  if (!s.recon.imported_at) return s.recon.prompt_copied_at ? 'prompt_copied' : 'not_started';
  if (!reconInventoryReady(s, opts.hasExistingSite)) return 'imported';
  return opts.factsAwaiting > 0 || opts.openReview > 0 ? 'needs_review' : 'complete';
}

/* ── Phase 4: build execution status — DERIVED from the stored record, never stored. ──────────── */

export const BUILD_EXEC_STATUSES = ['not_started', 'prompt_ready', 'building', 'result_ready', 'needs_attention', 'preview_ready', 'failed'] as const;
export type BuildExecStatus = (typeof BUILD_EXEC_STATUSES)[number];
export const BUILD_EXEC_STATUS_LABELS: Record<BuildExecStatus, string> = {
  not_started: 'Not started', prompt_ready: 'Prompt ready', building: 'Building', result_ready: 'Result ready',
  needs_attention: 'Needs attention', preview_ready: 'Preview ready', failed: 'Failed',
};

/** What stops an imported result counting as PREVIEW READY, whatever Claude claimed. Empty = none. */
export function previewGateProblems(b: BuildExecution): string[] {
  const out: string[] = [];
  if (b.result_status !== 'preview_ready') return out;
  if (!/^https:\/\/[a-z0-9.-]+\.pages\.dev(\/|$)/i.test(b.preview_url)) out.push('Preview URL is not a pages.dev address');
  if (b.noindex_confirmed !== true) out.push('Preview noindex not confirmed');
  if (b.qa.seedContaminationPassed !== true || b.seed_hits.length) out.push('Seed-client contamination not cleared' + (b.seed_hits.length ? ': ' + b.seed_hits.slice(0, 5).join(', ') : ''));
  if (b.qa.buildPassed !== true) out.push('Production build did not pass');
  if (b.qa.linksPassed !== true) out.push('Link check did not pass');
  if (b.errors.length) out.push(b.errors.length + ' error(s) reported');
  return out;
}

/** Does this build replace an existing website? Derived from the state when the caller does not know
 *  better: a recorded source URL, an imported recon of a site, or its crawled pages. */
export function stateHasExistingSite(s: WebsiteBuildState): boolean {
  return !!(s.source_site_url || s.recon.source_url || s.manifest.pages.length || s.old_pages?.urls.length);
}

/** The pages that exist for the completeness check: what the build reported, else the page plan. */
export function builtOrPlannedPaths(s: WebsiteBuildState): string[] {
  const b = s.build_execution;
  return b.pages.length ? b.pages : s.pages.filter((p) => p.action === 'keep' || p.action === 'create').map((p) => p.path).filter(Boolean);
}

/** What LeadFinderOS already knows about the client, for the build standard's gate. DERIVED from the
 *  stored state, never stored: approved photos, review evidence (a kept review strength or a verified
 *  review profile), a working old-site form that was not removed, the areas-hub decision, verified
 *  credentials. */
export function standardEvidence(s: WebsiteBuildState): StandardEvidence {
  const verified = (key: string) => s.facts.some((f) => f.key === key && f.status === 'verified' && !!f.value.trim());
  const kept = (cat: string) => s.quality.strengths.some((x) => x.category === cat && x.disposition !== 'remove');
  return {
    approvedPhotos: s.manifest.assets.filter((a) => a.approval === 'approved' && a.type === 'photo').length,
    hasReviewEvidence: kept('reviews') || verified('review_profiles'),
    hadWorkingForm: kept('contact_form'),
    areasHubNeeded: s.quality.intents.areas_hub?.need === 'needed',
    hasCredentials: verified('accreditations'),
    hasPhotoStrength: kept('photography') || kept('gallery') || kept('projects'),
  };
}

/**
 * THE Preview Ready gate: the technical gate (previewGateProblems) PLUS the Findable quality standard
 * (websiteQuality.ts) — strengths decided, completeness assessed, and for an existing-site rebuild an
 * old-vs-new comparison that says the new site is clearly an upgrade. One list, used by the status,
 * the Preview panel and the retry prompt, so they can never disagree.
 */
export function previewReadyProblems(s: WebsiteBuildState, hasExistingSite: boolean = stateHasExistingSite(s)): string[] {
  const b = s.build_execution;
  if (b.result_status !== 'preview_ready') return [];
  return [
    ...previewGateProblems(b),
    ...qualityGateProblems({ quality: s.quality, upgrade: b.upgrade, hasExistingSite, paths: builtOrPlannedPaths(s) }),
    ...standardProblems(b.standard, standardEvidence(s)),
  ];
}

export function buildExecutionStatus(s: WebsiteBuildState, readyToBuild: boolean, hasExistingSite?: boolean): BuildExecStatus {
  const b = s.build_execution;
  if (b.result_imported_at) {
    if (b.result_status === 'failed') return 'failed';
    if (b.result_status === 'needs_attention') return 'needs_attention';
    if (b.result_status === 'preview_ready') return previewReadyProblems(s, hasExistingSite ?? stateHasExistingSite(s)).length ? 'needs_attention' : 'preview_ready';
    return 'result_ready';
  }
  if (b.started_at) return 'building';
  return readyToBuild ? 'prompt_ready' : 'not_started';
}
